<script setup lang="ts">
import {ref,onMounted} from 'vue';import axios from 'axios';import {useRouter,RouterLink} from 'vue-router';const router=useRouter(),items=ref<any[]>([]),error=ref(''),more=ref(false),busy=ref(false);
async function headers(){return {'X-XSRF-TOKEN':(await axios.get('/api/auth/csrf')).data.token};}
async function load(append=false){try{const {data}=await axios.get('/api/notifications',{params:{before:append?items.value.at(-1)?.id:0}});items.value=append?[...items.value,...data]:data;more.value=data.length===30;}catch{error.value='通知加载失败';}}
async function readAll(){if(!items.value.length)return;busy.value=true;try{await axios.post('/api/notifications/read-all',null,{params:{through:items.value[0].id},headers:await headers()});items.value.forEach(n=>n.unread=false);window.dispatchEvent(new Event('notifications-updated'));}catch{error.value='标记失败，请重试';}finally{busy.value=false;}}
async function open(n:any){try{await axios.post('/api/notifications/'+n.id+'/read',null,{headers:await headers()});window.dispatchEvent(new Event('notifications-updated'));router.push(n.link);}catch{error.value='打开通知失败';}}
onMounted(()=>load());
</script><template><section class="notifications"><header><div><p>SDU / MY INBOX</p><h1>消息通知</h1></div><button :disabled="busy" @click="readAll">一键已读</button><RouterLink to="/messages">所有私聊 →</RouterLink></header><p role="alert">{{error}}</p><p v-if="!items.length">暂时没有通知。</p><button v-for="n in items" :key="n.id" class="notice-row" :class="{unread:n.unread}" @click="open(n)"><i v-if="n.unread"></i><span><strong>{{n.title}}</strong><small>{{n.createdAt}} · {{n.unread?'未读':'已读'}}</small></span><span>→</span></button><button v-if="more" @click="load(true)">加载更多消息</button></section></template><style scoped>.notifications{flex:1;background:#f6f4ee;color:#293d3b;padding:35px 6%}header{display:flex;align-items:center;gap:25px;flex-wrap:wrap}header p{font-size:10px;letter-spacing:2px;color:#94744c}h1{font-size:30px;margin:15px 0}button{background:#304b49;color:white;border:0;border-radius:5px;padding:12px 20px;cursor:pointer}a{color:#94744c;font-size:13px}.notice-row{display:flex;align-items:center;gap:16px;width:100%;text-align:left;background:white;color:#304b49;border:1px solid #e8e5db;margin:15px 0;padding:22px}.notice-row.unread{background:#fff8e3;border-color:#e8d4a4}.notice-row i{width:8px;height:8px;background:#c64b43;border-radius:50%;flex-shrink:0}.notice-row>span:first-of-type{flex:1}strong{font-size:14px}small{display:block;font-size:10px;color:#8e917f;margin-top:9px}</style>
